//! Cargo-driven `ole32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is ole32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x7b4a0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ffa8000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ffa8000000u64)),
        o => panic!("ole32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/ole32/ole32_unknwn_r.o", "dll/win32/ole32/ole32_oleidl_r.o", "dll/win32/ole32/ole32_objidl_r.o", "dll/win32/ole32/dcom_r.o", "body", "engine:wine", "engine:uuid", "engine:pseh", "engine:oldnames", "import:oleaut32", "import:advapi32", "import:user32", "import:gdi32", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:chkstk", "engine:delayimp_rust"],
        "x86_64" => &["dll/win32/ole32/ole32_unknwn_r.o", "dll/win32/ole32/ole32_oleidl_r.o", "dll/win32/ole32/ole32_objidl_r.o", "dll/win32/ole32/dcom_r.o", "body", "engine:wine", "engine:uuid", "engine:pseh", "engine:oldnames", "import:oleaut32", "import:advapi32", "import:user32", "import:gdi32", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust"],
        "aarch64" => &["dll/win32/ole32/ole32_unknwn_r.o", "dll/win32/ole32/ole32_oleidl_r.o", "dll/win32/ole32/ole32_objidl_r.o", "dll/win32/ole32/dcom_r.o", "body", "engine:wine", "engine:uuid", "engine:pseh", "engine:oldnames", "import:oleaut32", "import:advapi32", "import:user32", "import:gdi32", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:chkstk", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // target_link_options(LINKER:--require-defined=...): defined up front, so the
    // body's definition wins over an import thunk of the same name.
    let require_defined: &[&str] = match arch.as_str() {
        "x86" => &["-Wl,--require-defined=_CreateErrorInfo@4", "-Wl,--require-defined=_GetErrorInfo@8", "-Wl,--require-defined=_SetErrorInfo@8"],
        "x86_64" => &["-Wl,--require-defined=CreateErrorInfo", "-Wl,--require-defined=GetErrorInfo", "-Wl,--require-defined=SetErrorInfo"],
        "aarch64" => &["-Wl,--require-defined=CreateErrorInfo", "-Wl,--require-defined=GetErrorInfo", "-Wl,--require-defined=SetErrorInfo"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/ole32",
        "dll/win32/ole32",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "COM_NO_WINDOWS_H",
        "ENTRY_PREFIX=OLE32_",
        "PROXY_CLSID=CLSID_PSFactoryBuffer",
        "WINE_REGISTER_DLL",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_OLE32_",
        "_ROAPI_",
        "_WIN32_WINNT=0x600",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .rust_staticlib("ole32-rust")
        .c_from_compile_db("ole32_shims", &["dll/win32/ole32/stubmanager_seh.c", "dll/win32/ole32/rpcss_seh.c", "dll/win32/ole32/guid.c", "dll/win32/ole32/dcom_p.c", "dll/win32/ole32/ole32_objidl_p.c", "dll/win32/ole32/ole32_oleidl_p.c", "dll/win32/ole32/ole32_unknwn_p.c", "dll/win32/ole32/proxy.dlldata.c", "dll/win32/ole32/dcom_i.c", "dll/win32/ole32/irot_c.c", "dll/win32/ole32/irpcss_c.c"])
        .rc("dll/win32/ole32/ole32res.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/ole32/ole32.spec", "ole32.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link_args(require_defined)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
